import React, { useState } from "react";
import api from "../services/api";

type Attendee = { name: string; email: string };

interface CreateEventFormProps {
  onCreated?: () => void;
}

export default function CreateEventForm({ onCreated }: CreateEventFormProps) {
  const [name, setName] = useState("");
  const [venue, setVenue] = useState("");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [attendees, setAttendees] = useState<Attendee[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const addAttendee = () => setAttendees(prev => [...prev, { name: "", email: "" }]);
  const updateAttendee = (i: number, field: keyof Attendee, value: string) =>
    setAttendees(prev => prev.map((a, idx) => idx === i ? { ...a, [field]: value } : a));

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setMessage(null);

    const payload = {
      name,
      venue,
      startTime: new Date(start).toISOString(),
      endTime: new Date(end).toISOString(),
      attendees,
    };

    try {
      await api.post("/api/Events", payload);
      setMessage("✅ Event created successfully!");
      setName(""); setVenue(""); setStart(""); setEnd(""); setAttendees([]);
      onCreated?.();
    } catch (err: any) {
      console.error(err);
      setError(err?.message || "Failed to create event.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      maxWidth: "600px",
      margin: "2rem auto",
      padding: "1.5rem",
      borderRadius: "8px",
      border: "1px solid #ddd",
      boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
      fontFamily: "Arial, sans-serif"
    }}>
      <h2 style={{ textAlign: "center", marginBottom: "1rem" }}>➕ Create Event</h2>

      {message && <p style={{ color: "green", textAlign: "center" }}>{message}</p>}
      {error && <p style={{ color: "red", textAlign: "center" }}>{error}</p>}

      <form onSubmit={submit} style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
        <input
          placeholder="Event Name"
          value={name}
          onChange={e => setName(e.target.value)}
          required
          style={{ padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <input
          type="datetime-local"
          value={start}
          onChange={e => setStart(e.target.value)}
          required
          style={{ padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <input
          type="datetime-local"
          value={end}
          onChange={e => setEnd(e.target.value)}
          required
          style={{ padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <input
          placeholder="Venue"
          value={venue}
          onChange={e => setVenue(e.target.value)}
          required
          style={{ padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <div>
          <h3>Attendees</h3>
          {attendees.map((a, i) => (
            <div key={i} style={{ display: "flex", gap: "0.5rem", marginBottom: "0.5rem", flexWrap: "wrap" }}>
              <input
                placeholder="Name"
                value={a.name}
                onChange={e => updateAttendee(i, "name", e.target.value)}
                required
                style={{ flex: "1", padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
              />
              <input
                placeholder="Email"
                type="email"
                value={a.email}
                onChange={e => updateAttendee(i, "email", e.target.value)}
                required
                style={{ flex: "1", padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>
          ))}
          <button
            type="button"
            onClick={addAttendee}
            style={{
              padding: "0.5rem 1rem",
              borderRadius: "4px",
              border: "none",
              backgroundColor: "#28a745",
              color: "#fff",
              cursor: "pointer",
            }}
          >
            + Add Attendee
          </button>
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            marginTop: "1rem",
            padding: "0.75rem",
            borderRadius: "4px",
            border: "none",
            backgroundColor: "#007bff",
            color: "#fff",
            fontSize: "1rem",
            cursor: loading ? "not-allowed" : "pointer",
          }}
        >
          {loading ? "Creating..." : "Create Event"}
        </button>
      </form>
    </div>
  );
}
